package com.bank.cdc;

// One CDC event: operation, key, new values, and a sequence defining order.
class ChangeRecord {
    enum Op { INSERT, UPDATE, DELETE }

    final Op op;
    final String accountId;     // key
    final String holderName;    // value
    final long balance;         // value
    final long seq;             // ordering (log offset / commit timestamp)

    ChangeRecord(Op op, String accountId, String holderName, long balance, long seq) {
        this.op = op;
        this.accountId = accountId;
        this.holderName = holderName;
        this.balance = balance;
        this.seq = seq;
    }
}
