package com.bank.cdc;

import java.util.LinkedHashMap;
import java.util.Map;
import java.util.logging.Logger;

// A Delta-like target keyed by account id, supporting atomic merge operations.
class DeltaTable {
    private static final Logger log = Logger.getLogger(DeltaTable.class.getName());

    private final Map<String, String> rows = new LinkedHashMap<>(); // accountId -> "name|balance"

    void upsert(String key, String name, long balance) {
        boolean existed = rows.containsKey(key);
        rows.put(key, name + "|" + balance);
        log.info(() -> (existed ? "UPDATE " : "INSERT ") + key + " → " + name + ", Rs." + balance);
    }

    void delete(String key) {
        if (rows.remove(key) != null) log.info(() -> "DELETE " + key);
    }

    boolean contains(String key) { return rows.containsKey(key); }
    int size() { return rows.size(); }
    Map<String, String> snapshot() { return new LinkedHashMap<>(rows); }
}
