package com.bank.cdc;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Batch CDC via MERGE INTO: reduce to latest change per key, then apply insert/update/delete.
class BatchCdcMerger {
    private static final Logger log = Logger.getLogger(BatchCdcMerger.class.getName());

    void merge(DeltaTable target, List<ChangeRecord> changes) {
        // Step 1: reduce to the LATEST change per key by sequence (dedup out-of-order batch).
        Map<String, ChangeRecord> latest = new HashMap<>();
        for (ChangeRecord c : changes) {
            ChangeRecord existing = latest.get(c.accountId);
            if (existing == null || c.seq > existing.seq) latest.put(c.accountId, c);
        }
        log.info(() -> "MERGE reduced " + changes.size() + " changes to " + latest.size()
                + " latest-per-key records");

        // Step 2: apply atomically (modeled as one pass).
        for (ChangeRecord c : latest.values()) {
            switch (c.op) {
                case DELETE -> target.delete(c.accountId);
                case INSERT, UPDATE -> target.upsert(c.accountId, c.holderName, c.balance);
            }
        }
        log.info(() -> "MERGE INTO complete — target now has " + target.size() + " rows (atomic)");
    }
}
