package com.bank.cdc;

import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.logging.Logger;

// Streaming CDC via APPLY CHANGES INTO: consume an ordered feed, apply latest-per-key, handle deletes.
class StreamingCdcApplier {
    private static final Logger log = Logger.getLogger(StreamingCdcApplier.class.getName());

    private final Map<String, Long> appliedSeq = new HashMap<>(); // highest seq applied per key

    void applyChanges(DeltaTable target, List<ChangeRecord> feedMicroBatch) {
        log.info(() -> "APPLY CHANGES INTO: processing micro-batch of " + feedMicroBatch.size() + " events");
        for (ChangeRecord c : feedMicroBatch) {
            long last = appliedSeq.getOrDefault(c.accountId, Long.MIN_VALUE);
            if (c.seq <= last) {
                log.warning(() -> "Skipping out-of-order/stale event for " + c.accountId
                        + " seq=" + c.seq + " (already applied " + last + ")");
                continue; // ordering: never apply an older change over a newer one
            }
            switch (c.op) {
                case DELETE -> target.delete(c.accountId);
                case INSERT, UPDATE -> target.upsert(c.accountId, c.holderName, c.balance);
            }
            appliedSeq.put(c.accountId, c.seq);
        }
        log.info(() -> "APPLY CHANGES complete — target has " + target.size() + " rows");
    }
}
