package com.bank.cdc;

import java.util.List;
import java.util.logging.Logger;

public class CdcDemo {
    private static final Logger log = Logger.getLogger(CdcDemo.class.getName());

    public static void main(String[] args) {
        DeltaTable accounts = new DeltaTable();

        // Seed: Rajesh and Priya already exist.
        accounts.upsert("SAV2001", "Rajesh Kumar", 1000000);
        accounts.upsert("CUR3001", "Priya Sharma", 250000);

        log.info("=== Batch CDC via MERGE INTO ===");
        // A batch with: a new account, TWO changes to SAV2001 (out of order), and a delete.
        List<ChangeRecord> batch = List.of(
            new ChangeRecord(ChangeRecord.Op.INSERT, "SAV2002", "Amit Verma", 50000, 10),
            new ChangeRecord(ChangeRecord.Op.UPDATE, "SAV2001", "Rajesh Kumar", 900000, 11),
            new ChangeRecord(ChangeRecord.Op.UPDATE, "SAV2001", "Rajesh Kumar", 950000, 13), // newer
            new ChangeRecord(ChangeRecord.Op.DELETE, "CUR3001", null, 0, 12));
        new BatchCdcMerger().merge(accounts, batch);
        log.info(() -> "After batch merge: " + accounts.snapshot());

        log.info("=== Streaming CDC via APPLY CHANGES INTO ===");
        StreamingCdcApplier applier = new StreamingCdcApplier();
        // A streaming micro-batch with a stale (out-of-order) event that must be skipped.
        List<ChangeRecord> feed = List.of(
            new ChangeRecord(ChangeRecord.Op.UPDATE, "SAV2002", "Amit Verma", 75000, 20),
            new ChangeRecord(ChangeRecord.Op.UPDATE, "SAV2002", "Amit Verma", 60000, 19), // stale → skip
            new ChangeRecord(ChangeRecord.Op.INSERT, "CUR3002", "Neha Rao", 300000, 21));
        applier.applyChanges(accounts, feed);
        log.info(() -> "Final accounts: " + accounts.snapshot());
    }
}
